        strip_fixed(format!("{:.*}", digits, value))
    } else {
        let mantissa = strip_fixed(sci[..epos].to_string());
        let sign = if exp < 0 { '-' } else { '+' };
        format!("{}e{}{:02}", mantissa, sign, exp.abs())
    }
}

fn strip_fixed(s: String) -> String {
