//! Rust port of /workspace/dataset/color/tests/test12.cpp
//!
//! Reads r, g, b floats from argv[1..3] (defaults 0.4, 0.2, 0.8) and prints
//! the HSL, HSV, CMYK and YUV conversions separated by spaces, matching the
//! C++ program's `std::cout` output byte-for-byte.

mod colorspace;
mod fmt;

use colorspace::{ColorConverter, Rgb};
use std::env;

/// Mimics `std::stof`: skips leading whitespace and parses a float.
fn stof(s: &str) -> f32 {
    s.trim_start().parse::<f32>().unwrap()
}

fn main() {
    let mut r: f32 = 0.4;
    let mut g: f32 = 0.2;
    let mut b: f32 = 0.8;

    let args: Vec<String> = env::args().collect();
    if args.len() > 3 {
        r = stof(&args[1]);
        g = stof(&args[2]);
        b = stof(&args[3]);
    }

    let rgb = Rgb::new(r, g, b);

    let hsl = ColorConverter::rgb_to_hsl(&rgb);
    let hsv = ColorConverter::rgb_to_hsv(&rgb);
    let cmyk = ColorConverter::rgb_to_cmyk(&rgb);
    let yuv = ColorConverter::rgb_to_yuv(&rgb);

    println!(
        "{} {} {} {} {} {} {} {} {} {} {} {} {}",
        fmt::cpp_float(hsl.h),
        fmt::cpp_float(hsl.s),
        fmt::cpp_float(hsl.l),
        fmt::cpp_float(hsv.h),
        fmt::cpp_float(hsv.s),
        fmt::cpp_float(hsv.v),
        fmt::cpp_float(cmyk.c),
        fmt::cpp_float(cmyk.m),
        fmt::cpp_float(cmyk.y),
        fmt::cpp_float(cmyk.k),
        fmt::cpp_float(yuv.y),
        fmt::cpp_float(yuv.u),
        fmt::cpp_float(yuv.v),
    );
}

//! Color space types and conversions, re-implemented from the behavior of the
//! C++ `ColorSpace` library (black-box port). All arithmetic is done in `f32`
//! to match the original library's `float` precision exactly.

pub struct Rgb {
    pub r: f32,
    pub g: f32,
    pub b: f32,
}

pub struct Hsl {
    pub h: f32,
    pub s: f32,
    pub l: f32,
}

pub struct Hsv {
    pub h: f32,
    pub s: f32,
    pub v: f32,
}

pub struct Cmyk {
    pub c: f32,
    pub m: f32,
    pub y: f32,
    pub k: f32,
}

pub struct Yuv {
    pub y: f32,
    pub u: f32,
    pub v: f32,
}

impl Rgb {
    pub fn new(r: f32, g: f32, b: f32) -> Rgb {
        Rgb { r, g, b }
    }
}

/// Matches `std::max(a, b)` semantics: `a < b ? b : a`.
fn cpp_max(a: f32, b: f32) -> f32 {
    if a < b {
        b
    } else {
        a
    }
}

/// Matches `std::min(a, b)` semantics: `b < a ? b : a`.
fn cpp_min(a: f32, b: f32) -> f32 {
    if b < a {
        b
    } else {
        a
    }
}

pub struct ColorConverter;

impl ColorConverter {
    pub fn rgb_to_hsl(rgb: &Rgb) -> Hsl {
        let (r, g, b) = (rgb.r, rgb.g, rgb.b);
        let max = cpp_max(r, cpp_max(g, b));
        let min = cpp_min(r, cpp_min(g, b));
        let l = (max + min) / 2.0;

        let (h, s);
        if max == min {
            h = 0.0;
            s = 0.0;
        } else {
            let d = max - min;
            s = if l > 0.5 {
                d / (2.0 - max - min)
            } else {
                d / (max + min)
            };
            let mut hue = if max == r {
                (g - b) / d + if g < b { 6.0 } else { 0.0 }
            } else if max == g {
                (b - r) / d + 2.0
            } else {
                (r - g) / d + 4.0
            };
            hue *= 60.0;
            h = hue;
        }
        Hsl { h, s, l }
    }

    pub fn rgb_to_hsv(rgb: &Rgb) -> Hsv {
        let (r, g, b) = (rgb.r, rgb.g, rgb.b);
        let max = cpp_max(r, cpp_max(g, b));
        let min = cpp_min(r, cpp_min(g, b));
        let v = max;

        let (h, s);
        if max == min {
            h = 0.0;
            s = 0.0;
        } else {
            let d = max - min;
            s = d / max;
            let mut hue = if max == r {
                (g - b) / d + if g < b { 6.0 } else { 0.0 }
            } else if max == g {
                (b - r) / d + 2.0
            } else {
                (r - g) / d + 4.0
            };
            hue *= 60.0;
            h = hue;
        }
        Hsv { h, s, v }
    }

    pub fn rgb_to_cmyk(rgb: &Rgb) -> Cmyk {
        let (r, g, b) = (rgb.r, rgb.g, rgb.b);
        let k = 1.0 - cpp_max(r, cpp_max(g, b));
        if k == 1.0 {
            Cmyk {
                c: 0.0,
                m: 0.0,
                y: 0.0,
                k,
            }
        } else {
            Cmyk {
                c: (1.0 - r - k) / (1.0 - k),
                m: (1.0 - g - k) / (1.0 - k),
                y: (1.0 - b - k) / (1.0 - k),
                k,
            }
        }
    }

    pub fn rgb_to_yuv(rgb: &Rgb) -> Yuv {
        let (r, g, b) = (rgb.r, rgb.g, rgb.b);
        Yuv {
            y: 0.299 * r + 0.587 * g + 0.114 * b,
            u: -0.147 * r - 0.289 * g + 0.436 * b,
            v: 0.615 * r - 0.515 * g - 0.1 * b,
        }
    }
}

//! Reproduces C++ `std::cout << value` default formatting for floats:
//! `%g`-style with 6 significant digits, trailing zeros stripped, and
//! scientific notation when the decimal exponent is < -4 or >= 6.

/// Formats an `f32` the way C++ `operator<<(std::ostream&, float)` does by
/// default. The float is promoted to `f64` exactly, as in C++.
pub fn cpp_float(value: f32) -> String {
    format_g(value as f64, 6)
}

fn format_g(value: f64, precision: usize) -> String {
    if value.is_nan() {
        return if value.is_sign_negative() {
            "-nan".to_string()
        } else {
            "nan".to_string()
        };
    }
    if value.is_infinite() {
        return if value < 0.0 {
            "-inf".to_string()
        } else {
            "inf".to_string()
        };
    }

    let p = if precision == 0 { 1 } else { precision };

    // Correctly rounded scientific form, used to decide the notation and to
    // determine the decimal exponent (like printf's %g does with %e).
    let sci = format!("{:.*e}", p - 1, value);
    let epos = sci.find('e').unwrap();
    let exp: i32 = sci[epos + 1..].parse().unwrap();

    if exp >= -4 && exp < p as i32 {
        // Fixed notation with (p - 1 - exp) digits after the decimal point.
        let digits = (p as i32 - 1 - exp) as usize;
        strip_trailing_zeros(format!("{:.*}", digits, value))
    } else {
        // Scientific notation, exponent at least two digits with sign.
        let mantissa = strip_trailing_zeros(sci[..epos].to_string());
        let sign = if exp < 0 { '-' } else { '+' };
        format!("{}e{}{:02}", mantissa, sign, exp.abs())
    }
}

/// Strips trailing fractional zeros and a trailing decimal point (%g style).
fn strip_trailing_zeros(s: String) -> String {
    if s.contains('.') {
        s.trim_end_matches('0').trim_end_matches('.').to_string()
    } else {
        s
    }
}

